#' Exact Tests for 2x2 Tables (Python)
#'
#' 
#' @param data .
#' @param group .
#' @param outcome .
#' @param counts .
#' @param event .
#' @param refLevel .
#' @param design .
#' @param alternative .
#' @param ciWidth .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$crosstab} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$tests} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$crosstab$asDF}
#'
#' \code{as.data.frame(results$crosstab)}
#'
#' @export
pyexacttests <- function(
    data,
    group = NULL,
    outcome = NULL,
    counts = NULL,
    event,
    refLevel,
    design = "independent",
    alternative = "twoSided",
    ciWidth = 95,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyexacttests requires jmvcore to be installed (restart may be required)")

    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(counts)) counts <- jmvcore::resolveQuo(jmvcore::enquo(counts))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(counts), counts, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in outcome) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyexacttestsOptions$new(
        group = group,
        outcome = outcome,
        counts = counts,
        event = event,
        refLevel = refLevel,
        design = design,
        alternative = alternative,
        ciWidth = ciWidth,
        showConsole = showConsole)

    analysis <- pyexacttestsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

